declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();$id=(int)($_GET['id']??0);AdminUi::header($id?'تفاصيل العميل':'العملاء','customers');echo AdminUi::flash();if($id){$q=db()->prepare('SELECT * FROM customers WHERE id=?');$q->execute([$id]);$c=$q->fetch();if(!$c)throw new RuntimeException('customer_not_found');$q=db()->prepare("SELECT q.*,p.name project_name FROM quotes q LEFT JOIN projects p ON p.id=q.project_id WHERE q.customer_id=? ORDER BY q.id DESC");$q->execute([$id]);$quotes=$q->fetchAll();$q=db()->prepare('SELECT * FROM payments WHERE customer_id=? ORDER BY id DESC');$q->execute([$id]);$payments=$q->fetchAll();$q=db()->prepare("SELECT p.* FROM customer_projects cp JOIN projects p ON p.id=cp.project_id WHERE cp.customer_id=? ORDER BY p.updated_at DESC");$q->execute([$id]);$projects=$q->fetchAll();$q=db()->prepare("SELECT m.* FROM messages m JOIN conversations x ON x.id=m.conversation_id WHERE x.customer_id=? ORDER BY m.id DESC LIMIT 40");$q->execute([$id]);$messages=$q->fetchAll();$q=db()->prepare('SELECT * FROM change_requests WHERE customer_id=? ORDER BY id DESC');$q->execute([$id]);$changes=$q->fetchAll();?>
